import React from "react";

const points = [
  'Phishing bisa dicegah.',
  'Edukasi & kesadaran adalah kunci.',
  'Jangan klik sebelum yakin!',
];

export default function Slide13Penutup() {
  return (
    <div className="slide-content bg-gradient-to-r from-[#e6f4ea] to-[#b7e0c7] rounded-2xl p-8 md:p-12 shadow-xl">
      <h2 className="slide-title mb-6 text-green-700">Penutup & CTA</h2>
      <ul className="text-lg text-gray-800 mb-6 space-y-3">
        {points.map((pt, i) => (
          <li key={pt} className="flex items-center gap-3"><span className="text-green-600">✔</span>{pt}</li>
        ))}
      </ul>
      <div className="text-gray-700 mb-8">Mulai hari ini, cek ulang setiap email yang Anda terima. Jangan mudah percaya, selalu verifikasi.</div>
    </div>
  );
}
